	public static HashSet<Module_Unit.Unit> GetTargetsFromFlightPlan(ActiveUnit theUnit)
	{
		if (theUnit.Navigator.get_Flight(HierarchySearch: true).Cache_FP_Targets != null)
		{
			return theUnit.Navigator.get_Flight(HierarchySearch: true).Cache_FP_Targets;
		}
		Waypoint[] flightPlan = theUnit.Navigator.get_Flight(HierarchySearch: true).FlightPlan;
		HashSet<Module_Unit.Unit> hashSet = default(HashSet<Module_Unit.Unit>);
		foreach (Waypoint waypoint in flightPlan)
		{
			if (!((waypoint.Type == Waypoint.WaypointType.Target) | (waypoint.Type == Waypoint.WaypointType.WeaponLaunch) | (waypoint.Type == Waypoint.WaypointType.WeaponTarget)) || waypoint.TargeteeringList == null)
			{
				continue;
			}
			foreach (Mission.TargeteeringEntry targeteering in waypoint.TargeteeringList)
			{
				string target_ActualUnitObjectID = targeteering.Target_ActualUnitObjectID;
				string target_ContactObjectID = targeteering.Target_ContactObjectID;
				ActiveUnit value = null;
				Contact value2 = null;
				if (theUnit.ParentScen.ActiveUnits.TryGetValue(target_ActualUnitObjectID, out value))
				{
					if (hashSet == null)
					{
						hashSet = new HashSet<Module_Unit.Unit>();
					}
					hashSet.Add(value);
				}
				else if (theUnit.get_UnitSide(SetSideOnly: false).Contacts.TryGetValue(target_ContactObjectID, out value2))
				{
					if (hashSet == null)
					{
						hashSet = new HashSet<Module_Unit.Unit>();
					}
					hashSet.Add(value2);
				}
				else
				{
					_ = Debugger.IsAttached;
				}
			}
		}
		theUnit.Navigator.get_Flight(HierarchySearch: true).Cache_FP_Targets = hashSet;
		return hashSet;
	}

