	public static void DetermineLocalTimeForWaypoints(ref Scenario theScen, ref Waypoint[] thePlottedCourse, bool IsWingman)
	{
		int num = thePlottedCourse.Count() - 1;
		for (int i = 0; i <= num; i++)
		{
			Waypoint waypoint = thePlottedCourse[i];
			if (Information.IsNothing((object)waypoint.Time_Zulu))
			{
				waypoint.Time_Local = null;
				waypoint.Time_Local_Weapon = null;
				continue;
			}
			bool use_DST = theScen.Use_DST;
			string dST_Start = theScen.DST_Start;
			string dST_End = theScen.DST_End;
			waypoint.Time_Local = Misc.LocalTime(waypoint.Time_Zulu.Value, waypoint.Longitude, use_DST, dST_Start, dST_End);
			if (!Information.IsNothing((object)waypoint.Time_Zulu_Weapon))
			{
				waypoint.Time_Local_Weapon = Misc.LocalTime(waypoint.Time_Zulu_Weapon.Value, waypoint.Longitude, use_DST, dST_Start, dST_End);
			}
			else
			{
				waypoint.Time_Local_Weapon = null;
			}
		}
	}

	public static float clampAltitudeToKinematicLimits(ActiveUnit ac, float desiredAltitude)
	{
		float maximumAltitude = ac.Kinematics.GetMaximumAltitude();
		float minimumAltitude = ac.Kinematics.GetMinimumAltitude();
		if (desiredAltitude <= maximumAltitude)
		{
			if (desiredAltitude < minimumAltitude)
			{
				desiredAltitude = minimumAltitude;
			}
		}
		else
		{
			desiredAltitude = maximumAltitude;
		}
		return desiredAltitude;
	}

	public static void DetermineTimesAndFuelQty(ref Mission.Flight theFlight, ref Waypoint[] thePlottedCourse, ref ActiveUnit theAU, ref float NecessaryFuel, ref float MissionFuel, ref bool IsOnIngressLeg, bool IsWingman, bool NewFlightPlan, string theWingmanText, bool IsManouverForSpace)
